import math
import random

GROUP = "combinatorics"
SKILL = "induction"

def generate(seed):
    rng = random.Random(seed)
    n = rng.randint(5, 15)
    k = rng.randint(1, n)

    # Base case: when n = k, there is only one way to choose all elements, 
    # and when n > k, the inclusion of the specific subset of size k is irrelevant.
    if n == k:
        answer = math.comb(n, k)
    else:
        answer = math.comb(n, k) if k <= n else math.comb(n - 1, k)

    # Independent route: consider the problem step by step for small values of n and use induction.
    def count_ways(n, k):
        if n < k:
            return math.comb(n - 1, k)
        elif n == k:
            return math.comb(n, k)
        else:
            return math.comb(n, k)

    check = count_ways(n, k)
    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Given a set with {n} elements and a specific subset of size {k}, "
        f"find the number of ways to choose {k} elements from this set such that the inclusion of the specific subset does not affect the answer. "
        f"State only the integer."
    )
    return problem, str(answer)
